  'Draaien schrijft een gedraaide kopie naast het origineel; je oorspronkelijke bestand blijft ongewijzigd.':
      'Draaien skriuwt in draaide kopy neist it orizjineel; dyn oarspronklike bestân bliuwt ûnferoare.',
