  'Deze afbeelding naar het AI-model sturen?':
      'Dizze ôfbylding nei it AI-model stjoere?',
  'De afbeelding gaat ongewijzigd naar': 'De ôfbylding giet ûnferoare nei',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck lakket neat wei yn in ôfbylding: gesichten, tekst op in skermôfdruk en gegevens yn byld geane mei.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'De byldkontrôle fûn hjir ien of mear werkenbere gesichten.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Neist de eksport komme twa bestannen te stean dêr\'t in ûntfanger de redaksjes mei neigean kin.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'somt op wat weilitten is, sûnder de wearden sels. Dit bestân mei meistjoerd wurde mei it rapport.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'befettet de kaaien dêr\'t eltse redigearre wearde mei werom te rekkenjen is. Stjoer dit bestân net mei: dan is de redaksje ûngedien makke. Bewarje it by de boarne.',
  'slides': 'slides',
  'Achtergehouden': 'Efterhâlden',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Efterhâlden: strenger klassifisearre as de presintaasje',
  '1 slide achtergehouden door haar TLP': '1 dia efterhâlden troch har TLP',
  'slides achtergehouden door hun TLP': 'dia\'s efterhâlden troch harren TLP',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Dizze slides geane net mei by it presintearjen, eksportearjen of yn it pakket. Ferheegje it TLP-nivo fan de presintaasje by Presintaasje-ynfo om se mei te nimmen.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Alle dia\'s binne efterhâlden troch harren TLP-klassifikaasje — neat om sjen te litten.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Alle dia\'s binne efterhâlden troch harren TLP-klassifikaasje — neat om te eksportearjen.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Alle dia\'s binne oerslein of efterhâlden troch harren TLP-klassifikaasje — neat om sjen te litten.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Alle dia\'s binne oerslein of efterhâlden troch harren TLP-klassifikaasje — neat om te eksportearjen.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Grafykgetallen binne net bewarre — se steane allinne noch yn dit finster:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Yn de browser is der gjin crashherstel: slutsto dit ljepblêd, dan is net-bewarre wurk fuort. Bewarje dyn presintaasje sels.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  De lokale CVE-databank (do starte de download sels): OciDeck hellet de bulkgegevens op fia api.github.com en it releasebestân dêr\'t dat adres nei wiist.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  CVE opsykje (stiet standert út): stiet it oan, dan giet jo sykterm nei de ynstelde CVE-spegel en, as dy neat fynt, nei de Europeeske databank fan ENISA en nei MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  In ynsletten YouTube- of Vimeo-fideo laadt de spiler by dy tsjinst.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Yn de browser: wegeret de browser in adres streekrjocht op te heljen, dan besiket OciDeck it fia de server dêr\'t de app weikomt; dat adres komt dan by dy server telâne.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'It ynlûken is net fêstlein. By de folgjende start jildt jo tastimming wer.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'In tuskenkop dy\'t in nij diel fan de presintaasje oankundiget. Hâld it koart. Foegje fia de ôfbyldingsbibleteek in eftergrûnbyld ta.',
  'Bronnen doorzoeken…': 'Boarnen trochsykje…',
  'Niet doorzocht': 'Net trochsocht',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Dizze kontrôle draait net yn de webferzje: gesichtsherkenning fereasket in systeembibleteek dy\'t de browser net hat. Brûk de desktopferzje om ôfbyldings op gesichten nei te sjen.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'It token hat lês- en skriuwrjochten op it repository nedich. Gitea en Forgejo kenne gjin sykjen op de tsjinner; OciDeck siket lokaal.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'It token hat de repo-scope nedich (of fynkorrelich: Contents lêze en skriuwe).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'It token hat read_repository, write_repository en read_api nedich. Sykjen op de tsjinner freget Advanced of Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Rappe sykopdracht op de tsjinner — troch yndeksearringsfertraging kin in krekt wizige deck ûntbrekke.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Media bliuwt net bewarre yn in keal .md-bestân',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Ôfbyldings, fideo en audio dy\'tsto yn dit ljepblêd keazen hast, libje allinne yn it ûnthâld. In keal .md-bestân bewarret se net — by it opnij iepenjen binne se fuort. Eksportearje as .ocideck-pakket om de media mei te nimmen.',
