      'It sertifikaat fan dizze endpoint wurdt net fertroud. By in sels hoste endpoint kinst it besjen en fertrouwe by Ynstellingen → Opslach.',
  'Het certificaat van de forge wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'It sertifikaat fan de forge wurdt net fertroud — sels-ûndertekene, ferrûn, of op in oare namme steld.',
  'Het certificaat van het endpoint wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'It sertifikaat fan de endpoint wurdt net fertroud — sels-ûndertekene, ferrûn, of op in oare namme steld.',
  'creditcardnummer': 'kredytkaartnûmer',
  'beveiligingscode van een creditcard': 'befeiligingskoade fan in kredytkaart',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'gegevens yn de sprekersnotysjes — ûnsichtber op de dia, wol yn de eksport',
  'Certificaat vertrouwen?': 'Sertifikaat fertrouwe?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'It sertifikaat fan dizze server is net ûndertekene troch in erkende útjouwer. Dat is gewoan by in sels hoste server, mar sa sjocht in ôflústere ferbining der ek út.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Ferlykje de fingerprint hjirûnder mei wat dyn server sels toant. Komme se oerien, dan praatst mei de goede masine.',
  'Uitgegeven aan': 'Utjûn oan',
  'Uitgegeven door': 'Utjûn troch',
  'Geldig tot': 'Jildich oant',
  'Vingerafdruk (SHA-256)': 'Fingerôfdruk (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Allinnich dit iene sertifikaat wurdt fertroud. Ferfangt de server it letter, dan freget OciDeck it opnij.',
  'Vertrouwen': 'Fertrouwe',
  'Certificaat bekijken': 'Sertifikaat besjen',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'De plakken dêr\'tst dyn presintaasjes bewarrest en trochsikest — mappen op dizze kompjûter, WebDAV-servers, S3-buckets en git-repositories trochinoar. Sleep se yn de folchoarder dy\'tst wolst: de boppeste fan in soarte jildt as standert.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  S3-opslach: ferbynst dy mei in bucket, dan wurde it endpoint, de bucketnamme en dyn tagongskaai bewarre (de geheime kaai feilich yn de kaaibosk fan dyn systeem) en wurde de presintaasjes dy\'tst iepenst of bewarrest nei dy opslachtsjinst stjoerd.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Git-opslach: ferbynst dy mei in repository, dan wurdt dyn tagongstoken bewarre (feilich yn de kaaibosk fan dyn systeem) en wurde de presintaasjes dy\'tst bewarrest as commits nei dy server stjoerd. In wurkkopy fan de repository bliuwt ûnfersifere op dit apparaat stean.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Foar de taal fan dit deck ûntbrekke de sykte- en oandwaningsnammen. Religy, politike oertsjûging en fakbûnstermen wurde wol herkend, en kontrôlesifers (BSN, IBAN, paspoart) wurkje altyd — mar rekkenje der net op dat in diagnoaze fûn wurdt.',
  'niet getest': 'net test',
  'Werkte op': 'Wurke op',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Do bist oanmeld, mar hast hjir gjin tagong. Dyn wachtwurd is net it probleem — freegje de behearder om rjochten op dizze map.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Dyn token is jildich, mar mei dit net. Jou it mear rjochten, of wachtsje as de forge in limyt oplegt.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'It token is jildich, mar mei dit net — jou it mear rjochten op de repository.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Oanmeld, mar gjin tagong — dyn wachtwurd is net it probleem. Freegje rjochten op dizze map.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Dit liket in folsleine DAV-URL. By Nextcloud liedt OciDeck dat paad sels ôf — hjir heart allinnich de server.',
