  'Slides, notities, tabellen, code, bestandspaden en URL\'s worden op dit apparaat doorzocht op identificerende nummers, financiële gegevens, contactgegevens, digitale identificatoren, geheimen, bijzondere persoonsgegevens (AVG art. 9/10), massagegevens en metadatalekken.':
      'Slides, notysjes, tabellen, koade, bestânspaden en URL\'s wurde op dit apparaat trochsocht op identifisearjende nûmers, finansjele gegevens, kontaktgegevens, digitale identifikatoaren, geheimen, bysûndere persoansgegevens (AVG art. 9/10), massagegevens en metadatalekken.',
  'Alleen een zekere treffer waarschuwt; waarschijnlijk en mogelijk blijven informatief. Een uitgezette regel vuurt nergens.':
      'Allinne in wisse treffer warskôget; wierskynlik en mooglik bliuwe ynformatyf. In útsette regel fjurret nearne.',
  'Niet gecontroleerd: persoonsgegevens, bijzondere gegevens en geheimen. De privacycontrole staat uit bij Beveiliging.':
      'Net kontrolearre: persoansgegevens, bysûndere gegevens en geheimen. De privacykontrôle stiet út by Befeiliging.',
  'Op deze slide': 'Op dizze dia',
  'Tijdens presenteren': 'Under it presintearjen',
  'Classificatie en privacy': 'Klassifikaasje en privacy',
  'Logo tonen': 'Logo toane',
  'Footer tonen': 'Foettekst toane',
  'Tabel bewerkbaar': 'Tabel te bewurkjen',
  'Laat je de tabel tijdens het presenteren voor de zaal aanpassen. Staat standaard uit.':
      'Lit dy de tabel ûnder it presintearjen foar de seal oanpasse. Stiet standert út.',
  'Automatisch doorgaan': 'Automatysk trochgean',
  'Persoonsgegevens': 'Persoansgegevens',
  'Wijzigen': 'Feroarje',
  'Automatisch afspelen': 'Automatysk ôfspylje',
  'Melden': 'Melde',
  'Geaccepteerd': 'Akseptearre',
  'Gewaarschuwd': 'Warskôge',
  'Weggelaten': 'Weilitten',
  'Bewerkbaar': 'Te bewurkjen',
  'De privacycontrole': 'De privacykontrôle',
  'OciDeck leest je dia\'s na op gegevens die privacygevoelig kunnen zijn: identificatienummers, contactgegevens, telefoonnummers, bankrekeningen, sleutels en wachtwoorden, en bijzondere persoonsgegevens. Dat gebeurt volledig op dit apparaat: er wordt niets verstuurd, en de gevonden waarde zelf komt in geen enkele melding te staan.':
      'OciDeck lêst dyn dia\'s nei op gegevens dy\'t privacygefoelich wêze kinne: identifikaasjenûmers, kontaktgegevens, telefoannûmers, bankrekkens, kaaien en wachtwurden, en bysûndere persoansgegevens. Dat bart folslein op dit apparaat: der wurdt neat ferstjoerd, en de fûne wearde komt yn gjin inkelde melding te stean.',
  'De controle garandeert niet dat alles wordt gevonden; ze verkleint de kans dat er persoonsgegevens onbedoeld uitlekken.':
      'De kontrôle garandearret net dat alles fûn wurdt; se ferlytset de kâns dat persoansgegevens ûnbedoeld útlekke.',
  'Tekst in afbeeldingen blijft buiten beeld, gelinkte bestanden worden niet geopend, en gegevens zonder herkenbaar patroon herkent geen enkele scanner. Een dia zonder meldingen is een dia waarin wíj niets hebben gevonden, niet een dia waarvan vaststaat dat er niets in staat. Wat je deelt, blijft jouw beslissing en jouw verantwoordelijkheid.':
      'Tekst yn ôfbyldings bliuwt bûten byld, keppele bestannen wurde net iepene, en gegevens sûnder werkenber patroan werkent gjin inkelde scanner. In dia sûnder meldingen is in dia dêr\'t *wy* neat yn fûn hawwe, net in dia dêr\'t fêststiet dat der neat yn stiet. Wat do dielst, bliuwt dyn beslissing en dyn ferantwurdlikheid.',
  'telefoonnummer': 'telefoannûmer',
  'Voor wie is deze export?': 'Foar wa is dizze eksport?',
  'Volledig': 'Folslein',
  'Geredigeerd': 'Redigearre',
  'Voor de opdrachtgever of auditor: alleen wat je zelf op "weglaten" hebt gezet, gaat eruit. De rest blijft leesbaar, zodat een derde partij de bevindingen kan controleren.':
      'Foar de opdrachtjouwer of auditor: allinnich watst sels op "weilitte" set hast, giet derút. De rest bliuwt lêsber, sadat in tredde partij de befinings kontrolearje kin.',
  'Voor de bredere kring: alles wat de controle vindt gaat eruit, ook op slides die je hebt geaccepteerd. Het bestand krijgt "-geredigeerd" in de naam.':
      'Foar de bredere rûnte: alles wat de kontrôle fynt giet derút, ek op dia\'s dy\'tst aksepteare hast. It bestân krijt "-geredigeerd" yn de namme.',
  'tabel met persoonsgegevens (rijen×kolommen)':
      'tabel mei persoansgegevens (rigen×kolommen)',
  'massa-persoonsgegevens op één slide': 'massa-persoansgegevens op ien dia',
  'gebruikerspad met een naam erin': 'brûkerspaad mei in namme deryn',
  'toegangstoken in een link': 'tagongstoken yn in keppeling',
  'persoonsgegeven in een link': 'persoansgegeven yn in keppeling',
  'deellink met ingebakken toegang': 'dielkeppeling mei ynboude tagong',
  'e-mailadres in een link': 'e-mailadres yn in keppeling',
  'ingesloten afbeelding — wij kunnen er niet in kijken':
      'ynsletten ôfbylding — wy kinne der net yn sjen',
  'Je eigen gegevens': 'Dyn eigen gegevens',
  'Eén per regel: je naam, e-mailadres, telefoonnummer of het domein van je organisatie. Wat hier staat wordt niet gemeld en niet geredigeerd — het is de afzender, geen bevinding. Een domein (example.org) dekt elk adres eronder.':
      'Ien de regel: dyn namme, e-mailadres, telefoannûmer of it domein fan dyn organisaasje. Wat hjir stiet wurdt net meld en net redigearre — it is de ôfstjoerder, gjin befining. In domein (example.org) dekt elk adres derûnder.',
  'Bij onafgehandelde persoonsgegevens': 'By ûnôfhannele persoansgegevens',
  'Export afgebroken vanwege privacybevindingen.':
      'Eksport ôfbrutsen fanwegen privacybefinings.',
  'Export blokkeren': 'Eksport blokkearje',
  'Export geblokkeerd': 'Eksport blokkearre',
  'Export geblokkeerd: er staan persoonsgegevens in dit deck waarvoor nog geen keuze is gemaakt.':
      'Eksport blokkearre: yn dizze presintaasje steane persoansgegevens dêr\'t noch gjin kar oer makke is.',
  'Kies per slide wat er moet gebeuren, of exporteer bewust zoals het is.':
