  'Afbreken': 'Ofbrekke',
  'Afgebroken. Er is niets half achtergebleven.':
      'Ofbrutsen. Der is neat healwei achterbleaun.',
  'Bijwerken': 'Bywurkje',
  'Binnenhalen…': 'Ophelje…',
  'CVE\'s': 'CVE\'s',
  'Database ophalen': 'Databank ophelje',
  'De CVE-lijst kon niet worden opgehaald. Controleer je verbinding en probeer het opnieuw; een half binnengehaalde lijst is weggegooid.':
      'De CVE-list koe net ophelle wurde. Kontrolearje dyn ferbining en besykje it nochris; in healwei ophelle list is fuortsmiten.',
  'De nieuwste uitgave opzoeken…': 'De nijste útjefte opsykje…',
  'Dit is een grote download: ruim 500 MB binnenhalen, tijdelijk zo\'n 1,5 GB schijfruimte, en afhankelijk van je verbinding en apparaat al gauw tien tot dertig minuten werk. Daarna blijft er een index van enkele honderden megabytes staan. Op een verbinding die per megabyte betaalt, doe je dit liever niet.':
      'Dit is in grutte download: rom 500 MB ophelje, tydlik sa\'n 1,5 GB skiifromte, en ôfhinklik fan dyn ferbining en apparaat al gau tsien oant tritich minuten wurk. Dêrnei bliuwt der in yndeks fan inkele hûnderten megabytes stean. Op in ferbining dy\'t per megabyte betellet, dochst dit leaver net.',
  'Er was te weinig schijfruimte. De opbouw vraagt tijdelijk ruim 1,5 GB.':
      'Der wie te min skiifromte. De opbou freget tydlik rom 1,5 GB.',
  'Het opgehaalde archief was niet wat we verwachtten en is geweigerd. Er is niets geïnstalleerd.':
      'It ophelle argyf wie net wat wy ferwachten en is wegere. Der is neat ynstallearre.',
  'Indexeren…': 'Yndeksearje…',
  'Lokaal beschikbaar — opzoeken gebeurt offline, er gaat geen zoekterm naar buiten.':
      'Lokaal beskikber — opsykjen bart offline, der giet gjin sykterm nei bûten.',
  'Lokale CVE-database': 'Lokale CVE-databank',
  'Met de CVE-lijst op je eigen apparaat blijft het opzoeken hier: er gaat geen zoekterm meer naar een server, en niemand kan zien welk lek je onderzoekt.':
      'Mei de CVE-list op dyn eigen apparaat bliuwt it opsykjen hjir: der giet gjin sykterm mear nei in server, en nimmen kin sjen hokker lek do ûndersikest.',
  'Uitpakken…': 'Útpakke…',
  'Zet de volledige CVE-lijst op dit apparaat, zodat opzoeken offline gebeurt en je zoekterm nergens heen gaat. De database komt van CVE List V5 (het officiële CVE-programma, via GitHub).':
      'Set de folsleine CVE-list op dit apparaat, sadat opsykjen offline bart en dyn sykterm nearne hinne giet. De databank komt fan CVE List V5 (it offisjele CVE-programma, fia GitHub).',
  'Wat er lokaal beschikbaar is': 'Wat der lokaal beskikber is',
  'Nu bijwerken': 'No bywurkje',
  'Gegevens lokaal beschikbaar — het opzoeken gebeurt op dit apparaat, er gaat niets naar buiten.':
      'Gegevens lokaal beskikber — it opsykjen bart op dit apparaat, der giet neat nei bûten.',
  'Zwakheden (CWE)': 'Swakheden (CWE)',
  'Testgevallen (WSTG)': 'Testgefallen (WSTG)',
  'MIAUW-eisen': 'MIAUW-easken',
  'CVSS-scoretabel': 'CVSS-skoretabel',
  'Bevindingsjablonen': 'Befiningssjabloanen',
  'Zoek een instelling': 'Sykje in ynstelling',
  'Geen instelling gevonden': 'Gjin ynstelling fûn',
  'Je zoekterm gaat naar de ingestelde CVE-mirror, en als die niets vindt ook naar ENISA en MITRE. Wie die servers beheert, kan daaruit afleiden naar welk specifiek lek je zoekt — en dus welk lek je onderzoekt.':
      'Dyn sykterm giet nei de ynstelde CVE-mirror, en as dy neat fynt ek nei ENISA en MITRE. Wa\'t dy servers beheart, kin dêrút ôfliede nei hokker spesifyk lek ast sikest — en dus hokker lek ast ûndersikest.',
  'Accepteren': 'Akseptearje',
  'Accepteren + waarschuwen': 'Akseptearje + warskôgje',
  'Accepteren: de gegevens horen hier en de melding verdwijnt. Accepteren + waarschuwen: de ontvanger ziet een badge dat er persoonsgegevens op de slide staan. Weglaten: de gevonden gegevens worden onleesbaar gemaakt op het scherm en in de export — je markdown-bestand houdt de oorspronkelijke tekst.':
      'Akseptearje: de gegevens hearre hjir en de melding ferdwynt. Akseptearje + warskôgje: de ûntfanger sjocht in badge dat der persoansgegevens op de dia steane. Weilitte: de fûne gegevens wurde ûnlêsber makke op it skerm en yn de eksport — dyn markdown-bestân hâldt de oarspronklike tekst.',
  'Alleen melden': 'Allinnich melde',
  'PERSOONSGEGEVENS': 'PERSOANSGEGEVENS',
  'Volg de presentatie': 'Folgje de presintaasje',
  'Weglaten uit tonen en exporteren': 'Weilitte út toanen en eksportearjen',
  ' Overweeg dit te redigeren met [[dubbele blokhaken]].':
      ' Oerweagje it te redigearjen mei [[dûbele blokhaken]].',
  ' Zonder context in de tekst is dit mogelijk geen persoonsgegeven.':
      ' Sûnder kontekst yn \'e tekst is dit mooglik gjin persoansgegeven.',
  'Leest je dia\'s na op identificatienummers, contactgegevens en andere privacygevoelige gegevens, en meldt ze bij de kwaliteitscontrole. Dit gebeurt volledig op dit apparaat; er wordt niets verstuurd. Het is een hulpmiddel, geen garantie: tekst in afbeeldingen en gegevens zonder herkenbaar patroon blijven buiten beeld.':
      'Lêst dyn dia\'s nei op identifikaasjenûmers, kontaktgegevens en oare privacygefoelige gegevens, en meldt se by de kwaliteitskontrôle. Dit bart folslein op dit apparaat; der wurdt neat ferstjoerd. It is in helpmiddel, gjin garânsje: tekst yn ôfbyldings en gegevens sûnder werkenber patroan bliuwe bûten byld.',
  'Mogelijk persoonsgegeven': 'Mooglik persoansgegeven',
  'Privacycontrole': 'Privacykontrôle',
  'Waarschuw bij mogelijke persoonsgegevens':
      'Warskôgje by mooglike persoansgegevens',
  'burgerservicenummer (BSN)': 'boargerservicenûmer (BSN)',
  'bankrekeningnummer (IBAN)': 'bankrekkennûmer (IBAN)',
  'e-mailadres': 'e-mailadres',
  'De TSA-handtekening is niet in-app geverifieerd; alleen de hash komt overeen.':
      'De TSA-hantekening wurdt net yn de app ferifiearre; allinnich de hash komt oerien.',
  'Extern': 'Ekstern',
  'Van een externe URL opgehaald; het openen heeft die server benaderd.':
      'Fan in eksterne URL ophelle; it iepenjen hat dy server benadere.',
  'AI-assistentie (staat standaard uit): kies je een zelf-gehoste of cloud-backend, dan worden de teksten of afbeeldingen die je laat verwerken naar dat adres gestuurd. Wat je hebt geredigeerd, gaat er eerst uit. Een lokaal AI-model op dit apparaat verstuurt niets.':
      'AI-assistinsje (stiet standert út): kiest do in sels-hoste of cloud-backend, dan wurde de teksten of ôfbyldings dy\'tst ferwurkje litst nei dat adres stjoerd. Wat\'t do redigearre hast, giet der earst út. In lokaal AI-model op dit apparaat stjoert neat.',
  'Gegevens weglaten (redactie)': 'Gegevens weilitte (redaksje)',
  'Zet je tekst tussen dubbele blokhaken, zoals [[het adres]], dan laat OciDeck die weg uit alles wat je toont en exporteert. Op de dia, in de presentatie, in de PDF, de PowerPoint en de HTML verschijnen alleen blokken.':
      'Setst do tekst tusken dûbele blokhaken, lykas [[it adres]], dan lit OciDeck dy wei út alles watst toanst en eksportearrest. Op de dia, yn de presintaasje, yn de PDF, de PowerPoint en de HTML ferskine allinnich blokken.',
  'Weggelaten is écht weggelaten, niet afgedekt. De tekst zit niet als onzichtbare laag onder een zwart balkje in de PDF, niet in de sprekersnotities van de PowerPoint, en niet in de broncode van de HTML. Wie het bestand openmaakt, kan er niets uit terughalen.':
      'Weilitten is écht weilitten, net ôfdutsen. De tekst sit net as ûnsichtbere laach ûnder in swart balkje yn de PDF, net yn de sprekkersnotysjes fan de PowerPoint, en net yn de boarnekoade fan de HTML. Wa\'t it bestân iepenet, kin der neat út weromhelje.',
  'Je eigen bestand verandert niet. De oorspronkelijke tekst blijft in je markdown staan; redactie geldt alleen voor wat je deelt. Zo houd je je eigen gegevens.':
      'Dyn eigen bestân feroaret net. De oarspronklike tekst bliuwt yn dyn markdown stean; redaksje jildt allinnich foar watst dielst. Sa hâldst do dyn eigen gegevens.',
