  // Consent / license screen (redesign).
  'Ik ga akkoord met de EUPL 1.2-licentie en heb gelezen welke gegevens OciDeck bewaart.':
      'Ik gean akkoard mei de EUPL 1.2-lisinsje en haw lêzen hokker gegevens OciDeck bewarret.',
  'Lees de volledige licentie': 'Lês de folsleine lisinsje',
  'OciDeck is vrije software onder de EUPL 1.2-licentie. Voordat je begint, vragen we je de licentie te accepteren. Hieronder lees je ook welke gegevens OciDeck op dit apparaat bewaart en wanneer er iets je apparaat verlaat.':
      'OciDeck is frije software ûnder de EUPL 1.2-lisinsje. Foardatst begjinst, freegje we dy de lisinsje te akseptearjen. Hjirûnder lêst ek hokker gegevens OciDeck op dit apparaat bewarret en wannear\'t der wat dyn apparaat ferlit.',
  'OciDeck verzamelt geen statistieken en stuurt uit zichzelf niets naar buiten. Standaard blijft alles op dit apparaat. Gegevens verlaten dit apparaat alleen als jij dat kiest:\n\n•  Nextcloud/WebDAV: verbind je met een server, dan worden je inlognaam en wachtwoord bewaard (het wachtwoord veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die server verstuurd.\n•  Openen via URL: OciDeck haalt het bestand op van het adres dat je invoert.\n•  Online media (staat standaard uit): indien ingeschakeld laadt OciDeck afbeeldingen en video\'s van de adressen in je dia\'s.\n•  Externe links (zoals de online licentie) openen in je browser.':
      'OciDeck sammelet gjin statistiken en stjoert út himsels neat nei bûten. Standert bliuwt alles op dit apparaat. Gegevens ferlitte dit apparaat allinnich ast dat kiest:\n\n•  Nextcloud/WebDAV: ferbynst mei in server, dan wurde dyn ynlognamme en wachtwurd bewarre (it wachtwurd feilich yn de kaaibosk fan dyn systeem) en wurde de presintaasjes datst iepenst of bewarrest nei dy server stjoerd.\n•  Iepenje fia URL: OciDeck hellet it bestân op fan it adres datst ynfierst.\n•  Online media (stiet standert út): as ynskeakele laadt OciDeck ôfbyldings en fideo\'s fan de adressen yn dyn dia\'s.\n•  Eksterne keppelings (lykas de online lisinsje) iepenje yn dyn browser.',
  'OciDeck wordt geleverd onder de European Union Public Licence v1.2. Door akkoord te gaan aanvaard je deze licentie. Je mag OciDeck gebruiken, kopiëren, aanpassen en verspreiden onder de voorwaarden van de EUPL 1.2.':
      'OciDeck wurdt levere ûnder de European Union Public Licence v1.2. Troch akkoard te gean akseptearrest dizze lisinsje. Do meist OciDeck brûke, kopiearje, oanpasse en ferspriede ûnder de betingsten fan de EUPL 1.2.',
  'Om te werken en je werk niet te verliezen, bewaart OciDeck gegevens lokaal op dit apparaat:\n\n•  Je instellingen en voorkeuren (taal, mappen, stijl- en weergaveprofielen, recente bestanden).\n•  Je presentatiematerialen: de presentaties die je opslaat, automatische herstelkopieën en bijlagen zoals afbeeldingsbeschrijvingen.\n•  Deze toestemmingskeuze.\n\nJe kunt dit verwijderen door de bestanden te wissen of de instellingen te resetten.':
      'Om te wurkjen en dyn wurk net te ferliezen, bewarret OciDeck gegevens lokaal op dit apparaat:\n\n•  Dyn ynstellings en foarkarren (taal, mappen, styl- en werjefteprofilen, resinte bestannen).\n•  Dyn presintaasjematerialen: de presintaasjes datst bewarrest, automatyske werstelkopyen en bylagen lykas ôfbyldingsbeskriuwingen.\n•  Dizze tastimmingskar.\n\nDo kinst dit fuortsmite troch de bestannen te wiskjen of de ynstellings te resetten.',
  'Volledige licentie online (23 officiële taalversies)':
      'Folsleine lisinsje online (23 offisjele taalferzjes)',
